# unique_in_order :: 'AAAABBBCCDAABBB'
def unique_in_order(s):
    out = []
    for ch in s:
        if not out or out[-1] != ch:
            out.append(ch)
    return ''.join(out)

if __name__ == '__main__':
    print(unique_in_order('AAAABBBCCDAABBB'))

